import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createServer } from "node:net";
import { once } from "node:events";
import { chromium, expect } from "@playwright/test";
const reservation = createServer();
reservation.listen(0, "127.0.0.1");
await once(reservation, "listening");
const port = reservation.address().port;
await new Promise((resolve) => reservation.close(resolve));
const server = spawn(process.execPath, ["docs/design/2026-10-12-code-wiki/serve.mjs"], { env: { ...process.env, WIKI_PORT: String(port) }, stdio: ["ignore", "pipe", "pipe"] });
server.stderr.on("data", (data) => process.stderr.write(data));
const exited = once(server, "exit");
let browser;
try {
  await Promise.race([once(server.stdout, "data"), exited.then(() => { throw new Error("server exited before readiness"); })]);
  const base = `http://127.0.0.1:${port}`;
  browser = await chromium.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: true, chromiumSandbox: true });
  console.log("Browser", browser.version());
  const page = await browser.newPage({ viewport: { width: 1440, height: 960 } });
  const errors = [];
  page.on("pageerror", (error) => errors.push(error.message));
  await page.goto(base);
  const { data, sources } = await page.evaluate(() => ({ data: window.WIKI_DATA, sources: window.WIKI_SOURCES }));
  const manifest = await (await fetch(`${base}/snapshot-manifest.json`)).json();
  const refs = [...data.modules.flatMap((item) => item.sources), ...data.runtime, ...data.imports, ...data.flows.flatMap((item) => item.steps), ...data.conventions];
  for (const ref of refs) {
    const source = sources[`${ref.path}:${ref.line}`];
    assert.ok(source);
    assert.equal(source.text.split("\n").length, source.end - source.start + 1);
    assert.ok(manifest.entries.some((entry) => entry.path === source.path && entry.start === source.start && entry.end === source.end && entry.sha256 === source.sha256));
  }
  assert.equal(Object.keys(sources).length, 48);
  console.log("Snapshot references", Object.keys(sources).length);
  await expect(page.locator("#module-list .module-item")).toHaveCount(8);
  await expect(page.locator("#edge-list .edge-item")).toHaveCount(7);
  await page.getByRole("button", { name: "源码依赖", exact: true }).click();
  await expect(page.locator("#edge-list .edge-item")).toHaveCount(6);
  await page.locator("#search").fill("不存在的模块");
  await expect(page.locator("#empty")).toBeVisible();
  await page.getByRole("button", { name: "清除搜索", exact: true }).click();
  await expect(page.locator("#module-list .module-item")).toHaveCount(8);
  await page.screenshot({ path: "test-results/wiki-20261013-desktop.png", fullPage: true });
  await page.setViewportSize({ width: 390, height: 844 });
  await page.locator("#search").fill("沙箱");
  await page.getByRole("button", { name: "sbx / Guest", exact: true }).click();
  await expect(page.locator("#detail h2")).toHaveText("sbx / Guest");
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true);
  await page.getByRole("button", { name: "源码", exact: true }).click();
  const sourceButton = page.locator("#detail .source-link").first();
  await sourceButton.click();
  await expect(page.locator("#source-dialog")).toBeVisible();
  await expect(page.locator(".dialog-foot")).toContainText("非当前 PR 源码");
  await page.screenshot({ path: "test-results/wiki-20261013-mobile-source.png", fullPage: true });
  await page.keyboard.press("Escape");
  await expect(page.locator("#source-dialog")).not.toBeVisible();
  await expect(sourceButton).toBeFocused();
  await page.getByRole("button", { name: /关键流程/ }).click();
  await page.getByRole("button", { name: "取消空间任务", exact: true }).click();
  for (let step = 0; step < 5; step++) await page.locator("#next").click();
  await expect(page.locator("#next")).toBeDisabled();
  await expect(page.locator("#step-detail")).toContainText("等待停止确认");
  await page.reload();
  await expect(page.locator("#step-count")).toHaveText("6 / 6");
  await expect(page.locator("#next")).toBeDisabled();
  assert.deepEqual(errors, []);
  console.log("Desktop and 390px: graphs, search, source modal/Escape/focus, cancel flow and hash restore passed.");
} finally {
  if (browser) await browser.close();
  if (server.exitCode === null && server.signalCode === null) server.kill("SIGTERM");
  await exited;
}
